'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const NOTIFICATION_COOKIE = 'notifications-enabled'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const current = cookieStore.get(NOTIFICATION_COOKIE)?.value
  const nextValue = current === 'true' ? 'false' : 'true'

  cookieStore.set(NOTIFICATION_COOKIE, nextValue, {
    path: '/',
    httpOnly: true,
    sameSite: 'lax',
  })

  refresh()
}

